using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ParalyzeEffect", menuName = "Data/Battle/Effects/Enemy/Paralyze Effect")]
public class ParalyzeEffect : Effect
{
	[NonSerialized]
	private int oldEffectAmount;

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		oldEffectAmount = effectAmount;
		ReferenceSingleton<PlayerDiceHandHolder>.Instance.UpdateDrawDicesAmount(-effectAmount);
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		int num = effectAmount - oldEffectAmount;
		ReferenceSingleton<PlayerDiceHandHolder>.Instance.UpdateDrawDicesAmount(-num);
		oldEffectAmount = effectAmount;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		return 0;
	}
}
